return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sq','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-08T20:37:32+00:00','po-revision-date'=>'2026-09-08T20:37:32+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Një motor i plotë ruajtjeje në cache dhe optimizimi për WordPress: cache i faqes së plotë, cache i objekteve, pastrimi i bazës së të dhënave dhe optimizimi i CSS/JS. Instaloni këtë kur hosti juaj nuk ofron vetë një shtresë cache — në pritjen (hosting) Zinn Digital® instaloni në vend të tij Zinn® Cache. Ruajtja në cache e faqes së plotë kërkon një server LiteSpeed ose OpenLiteSpeed me modulin LSCache. Një version i shkëputur (fork) GPLv3 i spin-off-it të shtesës LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d orë','%d hour'=>'%d orë','%d minutes'=>'%d minuta','%d minute'=>'%d minutë','Purged All!'=>'U fshi gjithçka!','Purged the blog!'=>'Blogu u pastrua!','Purged the URL!'=>'URL-ja u pastrua!','Purged!'=>'Pastruar!','Failed to upgrade.'=>'Dështoi përmirësimi.','Upgraded successfully.'=>'Përmirësuar me sukses.','Dashboard'=>'Paneli i kontrollit','OptimaX'=>'OptimaX','Presets'=>'Parazgjedhjet','General'=>'Përgjithshme','Cache'=>'Keši','CDN'=>'CDN','Image Optimization'=>'Optimizimi i imazheve','Page Optimization'=>'Optimizimi